    n=len(f.get('fulfills',[]))
    a=agg[skill]; a[0]+=t; a[1]+=n; a[2]+=1
    if n: print(fid,skill,t,n,round(t/n,1))
tot=[0,0]
for s,(t,n,c) in agg.items():
    print(s,'turns',t,'assertions',n,'features',c,'per assertion',round(t/n,1) if n else None)
    tot[0]+=t; tot[1]+=n
print('worker total',tot, round(tot[0]/tot[1],1))
# M5 pending
for fid,f in feats.items():
    if f['milestone']=='m5': print(fid,f['skillName'],len(f.get('fulfills',[])),f.get('turnBudget'))
